<script setup lang="ts">
/**
 * A preview card shown on hover or focus (`design/components/hover-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/hover-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onMounted, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/hover-card'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  TOOLTIP_DELAY_MS,
  TOOLTIP_SKIP_DELAY_MS,
  anchorProps,
  devWarning,
  useDirection,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/hover-card.module.css'

export type HoverCardSide = NonNullable<HoverCardProps['side']>

export type HoverCardAlign = NonNullable<HoverCardProps['align']>

export interface HoverCardProps {
  align?: 'start' | 'center' | 'end'
  /**
   * Opens on mount, for galleries and tests; screens wait for the reader to hover.
   */
  defaultOpen?: boolean
  side?: 'bottom' | 'top' | 'right' | 'left'
}

defineOptions({ name: 'HoverCard', inheritAttrs: false })

const props = withDefaults(defineProps<HoverCardProps>(), {
  align: 'start',
  defaultOpen: undefined,
  side: 'bottom',
})
defineSlots<{
  default: (props: Record<string, never>) => unknown
  content: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const panel = useTemplateRef<HTMLElement>('panel')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    defaultOpen: props.defaultOpen,
    openDelay: TOOLTIP_DELAY_MS,
    closeDelay: TOOLTIP_SKIP_DELAY_MS,
    positioning: {
      placement: props.align === 'center' ? props.side : `${props.side}-${props.align}`,
      offset: { mainAxis: 4 },
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const present = usePresence(() => api.value.open, panel)
const effect1 = () => {
  devWarning(
    api.value.open &&
      panel.value?.querySelector(
        'a[href], button, input, select, textarea, [tabindex]:not([tabindex="-1"])',
      ) != null,
    'HoverCard: the preview contains interactive content, which keyboard and touch readers can never reach. A card the reader must operate is a Popover.',
  )
}
onMounted(effect1)
watch(() => api.value.open, effect1, { flush: 'post' })
</script>

<template>
  <span v-bind="anchorProps(api.getTriggerProps())" :class="styles.anchor">
    <slot />
  </span>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.panel"
        :hidden="undefined"
        data-member="hover-card"
      >
        <slot name="content" />
      </div>
    </div>
  </Teleport>
</template>
